description:
"/api/cart": {
  "get": {
    "tags": [
      "Cart"
    ],
    "summary": "Items in the current cart (signed-in user cart, or guest cart from the cookie)",
    "responses": {
      "200": {
        "description": "Cart items",
        "content": {
          "application/json": {
            "schema": {
              "type": "array",
              "items": {
                "$ref": "#/components/schemas/CartItem"
              }
            }
          }
        }
      }
    },
    "operationId": "getCart",
    "security": []
  },
  "post": {
    "tags": [
      "Cart"
    ],
    "summary": "Add a book. Quantity is added to what is already in the cart.",
    "requestBody": {
      "required": true,
      "content": {
        "application/json": {
          "schema": {
            "type": "object",
            "properties": {
              "bookId": {
                "type": "integer",
                "exclusiveMinimum": 0,
                "maximum": 9007199254740991
              },
              "quantity": {
                "type": "integer",
                "minimum": 1,
                "maximum": 999
              }
            },
            "required": [
              "bookId",
              "quantity"
            ]
          }
        }
      }
    },
    "responses": {
      "201": {
        "description": "Cart item with the new quantity",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/CartItem"
            }
          }
        }
      },
      "400": {
        "description": "VALIDATION_ERROR, OUT_OF_STOCK or INSUFFICIENT_STOCK",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      },
      "404": {
        "description": "BOOK_NOT_FOUND",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      }
    },
    "operationId": "addToCart",
    "security": []
  },
  "delete": {
    "tags": [
      "Cart"
    ],
    "summary": "Empty the cart",
    "responses": {
      "200": {
        "description": "Cleared",
        "content": {
          "application/json": {
            "schema": {
              "type": "object",
              "properties": {
                "message": {
                  "type": "string"
                }
              }
            }
          }
        }
      }
    },
    "operationId": "clearCart",
    "security": []
  }
},
"/api/cart/{id}": {
  "parameters": [
    {
      "name": "id",
      "in": "path",
      "required": true,
      "description": "Cart item id",
      "schema": {
        "type": "integer",
        "minimum": 1
      }
    }
  ],
  "put": {
    "tags": [
      "Cart"
    ],
    "summary": "Set the quantity of a cart item (must not exceed stock)",
    "requestBody": {
      "required": true,
      "content": {
        "application/json": {
          "schema": {
            "type": "object",
            "properties": {
              "quantity": {
                "type": "integer",
                "minimum": 1,
                "maximum": 999
              }
            },
            "required": [
              "quantity"
            ]
          }
        }
      }
    },
    "responses": {
      "200": {
        "description": "Updated item",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/CartItem"
            }
          }
        }
      },
      "400": {
        "description": "VALIDATION_ERROR, INVALID_ID or INSUFFICIENT_STOCK",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      },
      "404": {
        "description": "CART_ITEM_NOT_FOUND",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      }
    },
    "operationId": "updateCartItem",
    "security": []
  },
  "delete": {
    "tags": [
      "Cart"
    ],
    "summary": "Remove an item from the cart",
    "responses": {
      "200": {
        "description": "Removed",
        "content": {
          "application/json": {
            "schema": {
              "type": "object",
              "properties": {
                "message": {
                  "type": "string"
                }
              }
            }
          }
        }
      },
      "400": {
        "description": "Validation failed (code VALIDATION_ERROR, INVALID_JSON or INVALID_ID)",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      },
      "404": {
        "description": "CART_ITEM_NOT_FOUND",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      }
    },
    "operationId": "removeCartItem",
    "security": []
  }
},
"/api/cart/total": {
  "get": {
    "tags": [
      "Cart"
    ],
    "summary": "Cart total in dollars",
    "responses": {
      "200": {
        "description": "Total",
        "content": {
          "application/json": {
            "schema": {
              "type": "number",
              "examples": [
                59.97
              ]
            }
          }
        }
      }
    },
    "operationId": "getCartTotal",
    "security": []
  }
},
"/api/cart/merge": {
  "post": {
    "tags": [
      "Cart"
    ],
    "summary": "Move the guest cart into the signed-in user cart. The higher quantity wins, capped at stock.",
    "security": [
      {
        "sessionCookie": []
      }
    ],
    "responses": {
      "200": {
        "description": "Number of guest items processed",
        "content": {
          "application/json": {
            "schema": {
              "type": "object",
              "properties": {
                "merged": {
                  "type": "integer"
                }
              }
            }
          }
        }
      },
      "401": {
        "description": "Not signed in (code UNAUTHORIZED)",
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/Error"
            }
          }
        }
      }
    },
    "operationId": "mergeCart"
  }
},
